def _log_mode(config, events=None):
    """record/replay 按 config 形状选模式：fdb、forward、stp、loop-detect、
    link-forward、link-state、forward-static、forward-stp、forward-check/
    forward-decode（共享 ports,age,max_frame 三键配置，按帧形状区分）、
    stp-check/stp-decode（共享七键配置，按事件帧形状区分）、
    forward-stp-storm、lag、mirror、acl、acl-check、qos、qos-check/
    qos-decode（共享十二键配置，按事件帧形状区分）、security-check、
    mirror-check、lag-check、storm-check 或 port-security。

    events 非 None 时用于区分共享配置形状的两种模式：三键配置的非空帧
    数组含 src（八键）按 forward-check，含 data（t/port/data 原始帧）按
    forward-decode；两种帧形状混用报 InvalidInput；空数组沿用既有
    forward-decode 路由（既有日志字节不变）。stp 七键配置的非链路帧含
    src（九键）按 stp-check，含 data（t/port/data 原始帧）按 stp-decode；
    两种帧形状混用报 InvalidInput；仅链路项或空事件沿用既有 stp-decode
    路由（既有日志字节不变）。qos 十二键配置的帧项含 src（十键）按
    qos-check，含 data（t/port/data 原始帧）按 qos-decode，两种帧形状
    混用报 InvalidInput；仅链路/成员/service 项或空事件沿用既有
    qos-check 路由（既有日志字节不变）。
    """
    if isinstance(config, dict):
        keys = frozenset(config)
        # 恰含 ports,age 且 ports 为字符串数组时为 fdb 模式（forward 旧
        # 入口的 ports 为对象数组，形状不重叠）
        if keys == CONFIG_KEYS and isinstance(
            config.get("ports"), list
        ) and all(isinstance(p, str) for p in config["ports"]):
            return "fdb"
        # 恰含 ports,age 且 ports 为非空对象数组时为 forward 模式，旧式
        # access（name/vlan/up）与新式 802.1Q（name/mode/pvid/allowed/
        # untagged/up）两种端口形状均沿用 forward 入口识别与校验
        if (
            keys == CONFIG_KEYS
            and isinstance(config.get("ports"), list)
            and bool(config["ports"])
            and all(isinstance(p, dict) for p in config["ports"])
        ):
            return "forward"
        if keys == STP_CONFIG_KEYS:
            return "stp"
        if keys == LOOP_CONFIG_KEYS:
            return "loop"
        if keys == LINK_FORWARD_CONFIG_KEYS:
            return "link_forward"
        if keys == LINK_STATE_CONFIG_KEYS:
            return "link_state"
        if keys == FORWARD_STATIC_CONFIG_KEYS:
            return "forward_static"
        if keys == FORWARD_STP_CONFIG_KEYS:
            return "forward_stp"
        if keys == FORWARD_CHECK_CONFIG_KEYS:
            # forward-check 与 forward-decode 共享三键配置：非空帧数组含
            # src（八键）按 forward-check，含 data 按 forward-decode，两种
            # 帧形状混用即非法输入；空数组沿用既有 forward-decode 路由
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == FORWARD_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                else:
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "forward_check" if saw_src else "forward_decode"
        if keys == STP_CHECK_CONFIG_KEYS:
            # stp-check 与 stp-decode 共享七键配置：非链路帧含 src 按
            # stp-check，含 data 按 stp-decode，两种帧形状混用即非法输入
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == STP_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                elif ekeys != STP_EVENT_KEYS:
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "stp_check" if saw_src else "stp_decode"
        if keys == STORM_CONFIG_KEYS:
            return "forward_stp_storm"
        if keys == LAG_CONFIG_KEYS:
            return "lag"
        if keys == MIRROR_CONFIG_KEYS:
            return "mirror"
        if keys == ACL_CONFIG_KEYS:
            return "acl"
        if keys == ACL_CHECK_CONFIG_KEYS:
            return "acl_check"
        if keys == QOS_CONFIG_KEYS:
            return "qos"
        if keys == QOS_CHECK_CONFIG_KEYS:
            # qos-check 与 qos-decode 共享十二键配置：非链路/成员/service
            # 帧含 src（十键）按 qos-check，含 data（t/port/data 原始帧）
            # 按 qos-decode，两种帧形状混用即非法输入；无非帧帧项时沿用
            # 既有 qos-check 路由（既有日志字节不变）
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == QOS_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                elif ekeys not in (
                    STP_EVENT_KEYS, MEMBER_EVENT_KEYS, SERVICE_EVENT_KEYS
                ):
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "qos_decode" if saw_data else "qos_check"
        if keys == SECURITY_CHECK_CONFIG_KEYS:
            return "security_check"
        if keys == MIRROR_CHECK_CONFIG_KEYS:
            return "mirror_check"
        if keys == LAG_CHECK_CONFIG_KEYS:
            return "lag_check"
        if keys == STORM_CHECK_CONFIG_KEYS:
            return "storm_check"
    return "security"


def _run_fdb(config, events, observe, max_work=None):
    """record/replay fdb 模式：校验 fdb 配置与事件并执行仿真。

    语义同 fdb 子命令；max_work 非 None 时（record/replay）全量语义校验后
    先按 fdb 公式（逐事件累计 K+1，K 为老化前表项数）以独立空映射无副作用
    预演，首次超过即抛 FdbWorkLimit，不正式仿真。返回 (fdb 结果 dict,
    observer 或 None)；每项 output 恒 None，applied 与 version 由
    _build_log_doc/_verify_records 按 FDB 是否实际改变计算。

def stp_decode(
    bridges, links, delay, bridge_name, ports, age, max_frame, events,
    observer=None,
):
    # 原始帧按 frame-decode 规则解码为 stp-check 的九元组事件序
    # （alignment 恒真，分类退化为 runt/giant/bad_fcs/good），链路项原样
    # 保留；转发、学习与统计随后完全沿用 stp-check。observer 透传，由
    # stp-check 主体逐事件记录（record/replay）。
    raw_frames = [
        (item[1], item[2], item[3]) for item in events if item[0] == "frame"
    ]
    decoded_frames = _decode_raw_frames(raw_frames)
    decoded = []
    frame_index = 0
    for item in events:
        if item[0] == "link":
            decoded.append(item)
        else:
            t, port_name, src, dst, vlan, length, fcs, alignment = (
                decoded_frames[frame_index]
            )
            frame_index += 1
            decoded.append(
                ("frame", t, port_name, src, dst, vlan, length, fcs, alignment)
            )
    return forward_stp_check(
        bridges, links, delay, bridge_name, ports, age, max_frame, decoded,
        observer=observer,
    )


STORM_CHECK_CONFIG_KEYS = frozenset(
    ("bridges", "links", "delay", "bridge", "ports", "age", "storm",
     "max_frame")
)


QOS_DECODE_FRAME_KEYS = FRAME_DECODE_FRAME_KEYS  # {"t", "port", "data"}


def validate_qos_decode_events(events, ports, link_ids, lags):
    """qos-decode 事件：链路/成员/service 项与 t/port/data 原始帧按 t 非降混合。

    非帧项沿用 qos-check；帧子序列复用 forward-decode 全量校验（hex、
    最短长度、单层 8100、双标签拒绝、目的非全零、源非零单播），再在混合
    序上重放跨类型的 t 非降。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in ports}
    member_set = {member for lag in lags for member in lag["members"]}
    frame_docs = []
    frame_positions = set()
    for index, event in enumerate(events):
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == QOS_DECODE_FRAME_KEYS:
            frame_docs.append(event)
            frame_positions.add(index)
        elif keys not in (
            STP_EVENT_KEYS, MEMBER_EVENT_KEYS, SERVICE_EVENT_KEYS
        ):
            raise InvalidInput("bad event")
    # 帧子序列的外壳（hex、8100、双标签）与 MAC 规则同 forward-decode
    checked_frames = validate_forward_decode_frames(frame_docs, ports)
    raw_by_pos = dict(zip(sorted(frame_positions), checked_frames))
    result = []
    prev_t = None
    for index, event in enumerate(events):
        t = event["t"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:  # 各类型混合序上 t 非降
            raise InvalidInput("t not monotonic")
        prev_t = t
        if index in raw_by_pos:
            _, port_name, raw = raw_by_pos[index]
            result.append(("frame", t, port_name, raw))
            continue
        keys = frozenset(event)
        if keys == STP_EVENT_KEYS:
            lid = event["id"]
            up = event["up"]
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
        elif keys == MEMBER_EVENT_KEYS:
            member = event["member"]
            up = event["up"]
            if not isinstance(member, str) or member not in member_set:
                raise InvalidInput("bad event member")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("member", t, member, up))
        else:
            port = event["port"]
            count = event["count"]
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not _is_int(count) or count <= 0:
                raise InvalidInput("bad count")
            result.append(("service", t, port, count))
    return result


def _decode_qos_raw_frames(frames):
    """按 frame-decode 规则解析原始帧为 qos-check 的十元组帧序。

    无对齐概念，alignment 恒真；未标记帧 priority 恒为 0、vlan 为 None，
    分类退化为 runt/giant/bad_fcs/good。
    """
    checked = []
    for t, port, raw in frames:
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            priority = tci >> 13
            vlan = tci & 0x0FFF
            ethertype_offset = 16
        else:
            priority = 0
            vlan = None
            ethertype_offset = 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        fcs = raw[-4:] == (zlib.crc32(raw[:-4]) & 0xFFFFFFFF).to_bytes(
            4, "little"
        )
        checked.append(
            (
                t, port, src, dst, vlan, ethertype, priority,
                len(raw), fcs, True,
            )
        )
    return checked


def _decode_qos_events(events):
    """把校验后的 qos-decode 混合事件转为 qos-check 十一元组事件序。

    链路/成员/service 项原样保留，原始帧按 frame-decode 规则解码
    （alignment 恒真，未标记 priority 恒 0、vlan 为 None）；工作量预演与
    正式仿真共用同一转换，保证计费与执行同形。

def _decode_qos_events(events):
    """把校验后的 qos-decode 混合事件转为 qos-check 十一元组事件序。

    链路/成员/service 项原样保留，原始帧按 frame-decode 规则解码
    （alignment 恒真，未标记 priority 恒 0、vlan 为 None）；工作量预演与
    正式仿真共用同一转换，保证计费与执行同形。
    """
    raw_frames = [
        (item[1], item[2], item[3]) for item in events if item[0] == "frame"
    ]
    decoded_frames = _decode_qos_raw_frames(raw_frames)
    decoded = []
    frame_index = 0
    for item in events:
        if item[0] == "frame":
            t, port_name = item[1], item[2]
            (
                _, _, src, dst, vlan, ethertype, priority,
                length, fcs, alignment,
            ) = decoded_frames[frame_index]
            frame_index += 1
            decoded.append(
                ("frame", t, port_name, src, dst, vlan, ethertype, priority,
                 length, fcs, alignment)
            )
        else:
            decoded.append(item)
    return decoded


def qos_decode(
    bridges, links, delay, bridge_name, ports, age, storm, lags, mirror,
    acl, qos, max_frame, events, observer=None, state_out=None,
):
    # 原始帧按 frame-decode 规则解码为 qos-check 的十一元组事件序
    # （alignment 恒真，分类退化为 runt/giant/bad_fcs/good），链路、成员、
    # service 项原样保留；统计、转发、学习、镜像与队列随后完全沿用
    # qos-check。observer/state_out 透传，由 qos-check 主体逐事件记录。
    decoded = _decode_qos_events(events)
    return forward_qos_check(
        bridges, links, delay, bridge_name, ports, age, storm, lags, mirror,
        acl, qos, max_frame, decoded, observer=observer, state_out=state_out,
    )


def validate_storm_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != STORM_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # bridges/links/delay/bridge/ports/age/storm 与 forward-stp-storm 契约
    # 一致，复用其全量校验
    bridges, links, delay, bridge, ports, age, storm = (
        validate_forward_stp_storm_config(
            {key: config[key] for key in STORM_CONFIG_KEYS}
        )
    )
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    return bridges, links, delay, bridge, ports, age, storm, max_frame


